import{_ as a,m as i,n as t,q as l}from"./chunks/framework.DMDh-7Lg.js";const m=JSON.parse('{"title":"Klix Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),r={name:"index.md"};function n(o,e,s,c,h,d){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="klix-documentation" tabindex="-1">Klix Documentation <a class="header-anchor" href="#klix-documentation" aria-label="Permalink to &quot;Klix Documentation&quot;">​</a></h1><p>Klix is a Python framework for building terminal-first CLI applications with a session model, command routing, middleware, lifecycle events, typed state, and a small UI layer built on top of <code>prompt_toolkit</code> and <code>rich</code>.</p><p>This documentation is written against the current implementation in this repository. It explains what Klix can do today, how the pieces fit together, and where the current boundaries are.</p><p>If you are new to Klix, use this path:</p><ol><li>Read <a href="./installation">Installation</a></li><li>Work through <a href="./getting-started">Getting Started</a></li><li>Build the example in <a href="./quickstart">Quickstart</a></li><li>Read <a href="./concepts/architecture">Architecture</a></li><li>Use the focused guides in <a href="./guides/building-your-first-cli">Guides</a></li></ol><h2 id="documentation-map" tabindex="-1">Documentation Map <a class="header-anchor" href="#documentation-map" aria-label="Permalink to &quot;Documentation Map&quot;">​</a></h2><h3 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h3><ul><li><a href="./installation">Installation</a></li><li><a href="./getting-started">Getting Started</a></li><li><a href="./quickstart">Quickstart</a></li></ul><h3 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core concepts&quot;">​</a></h3><ul><li><a href="./concepts/architecture">Architecture</a></li><li><a href="./concepts/app">App</a></li><li><a href="./concepts/session">Session</a></li><li><a href="./concepts/commands">Commands</a></li><li><a href="./concepts/middleware">Middleware</a></li><li><a href="./concepts/events">Events</a></li><li><a href="./concepts/state">State</a></li><li><a href="./concepts/router">Router</a></li><li><a href="./concepts/input-engine">Input Engine</a></li><li><a href="./concepts/renderer">Renderer</a></li><li><a href="./concepts/layout">Layout</a></li><li><a href="./concepts/ui">UI Namespace</a></li></ul><h3 id="practical-guides" tabindex="-1">Practical guides <a class="header-anchor" href="#practical-guides" aria-label="Permalink to &quot;Practical guides&quot;">​</a></h3><ul><li><a href="./guides/building-your-first-cli">Building Your First CLI</a></li><li><a href="./guides/adding-commands">Adding Commands</a></li><li><a href="./guides/using-middleware">Using Middleware</a></li><li><a href="./guides/handling-events">Handling Events</a></li><li><a href="./guides/working-with-state">Working with State</a></li><li><a href="./guides/creating-ui">Creating UI</a></li><li><a href="./guides/input-modes">Input Modes</a></li><li><a href="./guides/autocomplete">Autocomplete</a></li><li><a href="./guides/persistence">Persistence</a></li><li><a href="./guides/theming">Theming</a></li></ul><h3 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h3><ul><li><a href="./components/input">Input Components</a></li><li><a href="./components/output">Output Components</a></li><li><a href="./components/widgets">Widgets Reference</a></li></ul><h3 id="example-walkthroughs" tabindex="-1">Example walkthroughs <a class="header-anchor" href="#example-walkthroughs" aria-label="Permalink to &quot;Example walkthroughs&quot;">​</a></h3><ul><li><a href="./examples/minimal">Minimal Example</a></li><li><a href="./examples/full-demo">Full Demo</a></li><li><a href="./examples/gemini-style-cli">Gemini-Style CLI</a></li></ul><h3 id="api-reference" tabindex="-1">API reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API reference&quot;">​</a></h3><ul><li><a href="./reference/api">API Overview</a></li><li><a href="./reference/commands">Command Reference</a></li><li><a href="./reference/events">Event Reference</a></li><li><a href="./reference/middleware">Middleware Reference</a></li><li><a href="./reference/errors">Error Reference</a></li><li><a href="./reference/config">Config Reference</a></li></ul><h3 id="project-docs" tabindex="-1">Project docs <a class="header-anchor" href="#project-docs" aria-label="Permalink to &quot;Project docs&quot;">​</a></h3><ul><li><a href="./contributing">Contributing</a></li><li><a href="./faq">FAQ</a></li></ul><h2 id="what-klix-gives-you" tabindex="-1">What Klix Gives You <a class="header-anchor" href="#what-klix-gives-you" aria-label="Permalink to &quot;What Klix Gives You&quot;">​</a></h2><ul><li>A single <code>App</code> object that owns registration and runtime flow</li><li>Per-session state through <code>Session</code></li><li>Slash-command parsing with schema validation</li><li>Middleware around command execution</li><li>Lifecycle and input events</li><li>Rich text rendering and fallback rendering</li><li>A UI namespace with input widgets and output widgets</li><li>A basic region-based layout model</li><li>A scaffold CLI through <code>klix init</code></li></ul><h2 id="what-klix-does-not-try-to-be" tabindex="-1">What Klix Does Not Try To Be <a class="header-anchor" href="#what-klix-does-not-try-to-be" aria-label="Permalink to &quot;What Klix Does Not Try To Be&quot;">​</a></h2><p>Klix is not a general terminal emulator and it is not a full-screen TUI framework in the <code>textual</code> sense. The current implementation favors a simple interactive command loop with composable utilities over a heavy runtime model.</p><p>That matters when you read the rest of these docs:</p><ul><li>layout support exists, but redraw behavior is still coarse</li><li>events exist, but only some are actively emitted by the current runtime</li><li>persistence exists, but it is intentionally minimal</li><li>widgets are reusable, but not every one is a complex full-screen experience</li></ul><p>Those details are documented explicitly in <a href="./concepts/architecture">Architecture</a>, <a href="./concepts/layout">Layout</a>, and <a href="./faq">FAQ</a>.</p>',27)])])}const p=a(r,[["render",n]]);export{m as __pageData,p as default};
